"use strict";exports.id=24721,exports.ids=[24721],exports.modules={24721:a=>{a.exports=JSON.parse('{"_status":"machine-draft, needs human review","Based on your answers, we are connecting you with immediate support. Please reach out for support now. This information is free and always available — no payment, no registration required.":"Iyadoo lagu salaynayo jawaabahaaga, waxaan kugu xiraynaa taageero degdeg ah. Fadlan hadda raadso taageero. Macluumaadkan waa bilaash, had iyo jeerna waa la heli karaa — lacag iyo diiwaangelin looma baahna.","Belonging & Community":"Ka-mid-noqoshada iyo Bulshada","Biological, Wellbeing and Health":"Bayoolaji, Ladnaan iyo Caafimaad","If you are in immediate danger, contact local emergency services or go to the nearest health facility now.":"Haddii aad ku jirto khatar degdeg ah, la xiriir adeegyada gurmadka deegaankaaga ama hadda aad xarunta caafimaadka kuugu dhow.","If you are struggling to meet your basic needs, these services can help. This information is free and always available.":"Haddii ay kugu adag tahay inaad daboosho baahiyahaaga aasaasiga ah, adeegyadan ayaa ku caawin kara. Macluumaadkan waa bilaash, had iyo jeerna waa la heli karaa.","Money & Business Reflection":"Milicsiga Lacagta iyo Ganacsiga","Peace & Harmony":"Nabad iyo Wada-noolaansho","Relationships & Family":"Xiriirka iyo Qoyska","Spiritual & Life Direction":"Ruuxi iyo Jihada Nolosha","being reviewed":"dib ayaa loo eegayaa","consultation requested":"la-tashi ayaa la codsaday","full report available":"warbixinta oo dhan waa la heli karaa","high":"sare","not submitted yet":"weli lama dirin","referral advised":"gudbin ayaa lagu taliyay","report ready":"warbixintu waa diyaar","support contacts shared":"xiriirada taageerada waa la wadaagay","urgent":"degdeg","waiting for a reviewer":"wuxuu sugayaa dib-u-eege"}')}};